<?php define('IN_CRONLITE',true);define('SYSTEM_ROOT',dirname(__FILE__).'/');define('ROOT',dirname(dirname(SYSTEM_ROOT)).'/');require_once(ROOT.'includes/common.php');require_once(ROOT.'includes/auth.php');require_login();require_role('advertiser');$user_id=get_current_user_id();$advertiser=$DB->query("SELECT * FROM ad_advertisers WHERE user_id=$user_id")->fetch();if(isset($_POST['submit'])){$amount=floatval($_POST['amount']);$channel=$_POST['channel'];$order_no='R'.time().mt_rand(1000,9999);$DB->query("INSERT INTO ad_recharge_orders(advertiser_id,order_no,amount,channel,status)VALUES({$advertiser['id']},'$order_no',$amount,'$channel',0)");header('Location:recharge.php?success=1');}include(ROOT.'admin/admin.php');?>
